    'mutations': faults + [dict(faults[0], tests=[base+'testLastDayOfFebruaryLeapYear', '-v']), dict(faults[1], tests=[base+'testNextWednesdayIsToday', '-v'])]
}
p = subprocess.run([sys.executable, '-B', '.agents/skills/con-artist/scripts/audit.py', '--source', '.', '--spec', '-'], input=json.dumps(spec), text=True, capture_output=True)
print('AUDIT CLI EXIT:', p.returncode)
if p.stderr: print(p.stderr)
try:
    data = json.loads(p.stdout)
except ValueError:
    print(p.stdout)
    raise SystemExit(p.returncode or 1)
for key, val in data.items():
    if key "'!= '"'audits': print(key, json.dumps(val))
for i, audit in enumerate(data.get('audits', [])):
    print('\\nAUDIT', i, ['cap28 selected', 'weekday selected', 'ignore months selected', 'cap28 leap witness', 'weekday today witness'][i])
    for key, val in audit.items():
        if key "'!= '"'checks': print(key, json.dumps(val))
    for name, result in audit.get('checks', {}).items():
        print('CHECK', name)
        for key, val in result.items():
            if key "'!= '"'output': print(key, json.dumps(val))
        print(result.get('output', ''))
raise SystemExit(p.returncode)
